<?php namespace App\Filament\Resources\ReturnTransactions\Schemas; use Filament\Forms\Components\DatePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Forms\Components\Textarea; use Filament\Forms\Components\Repeater; use Filament\Forms\Components\Hidden; use Filament\Schemas\Schema; class ReturnTransactionForm { public static function configure(Schema $schema): Schema { return $schema->components([ TextInput::make('return_code')->default(fn() => 'RET-'.date('Y').'-'.rand(1000, 9999))->required(), Select::make('type')->options(['retur_supplier' => 'Retur ke Supplier', 'retur_customer' => 'Retur dari Customer'])->required(), DatePicker::make('date')->default(now())->required(), Select::make('supplier_id')->relationship('supplier', 'name'), TextInput::make('customer_name'), Textarea::make('reason')->required(), Select::make('status')->options(['pending' => 'Pending', 'diproses' => 'Diproses', 'selesai' => 'Selesai', 'ditolak' => 'Ditolak'])->default('pending')->required(), Hidden::make('created_by')->default(fn() => auth()->id()), Repeater::make('items')->relationship('items')->schema([ Select::make('item_id')->relationship('item', 'name')->searchable()->required(), TextInput::make('quantity')->numeric()->required(), TextInput::make('price')->numeric()->required(), Select::make('condition')->options(['baik' => 'Baik', 'rusak' => 'Rusak', 'cacat' => 'Cacat'])->default('rusak')->required(), TextInput::make('notes'), ])->columnSpanFull()->columns(5) ]); } }